        scwin.teamTpCd();
        $('#ipt_comAbbrv').keydown(async function(key) {
                if (key.keyCode == 13) {
                    await scwin.searchList();
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil11050.onpageload' }); }
};

/**
