 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('cal_startDate').getValue() > $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('ipt_method').setValue("disclsConsultProcsList");
    $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do");
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


